def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change_ratio = ((v2 - v1) / v1) * 100

    return {
        "value": change_ratio,
        "trace": {
            "previous_value": v1,
            "current_value": v2,
            "change": v2 - v1,
            "change_ratio_percent": change_ratio,
            "output_meta": {
                "currency": "€",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
